	/** 
	 * jumpstart the process by instantiating2 Order
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		orderId = OrderService.getOrderInstance()
		.createOrder( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		OrderService.getOrderInstance()
				.createOrder( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.orderSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Order : " + successValue.getOrderId());
							  if (successValue.getOrderId().equals(orderId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfOrderList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Order test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on order consumed")
					);
			subscriber.orderSubscribe( orderId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Order : " + successValue.getOrderId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfOrderList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on order for orderId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Order. 
	 */
	protected Order read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Order" );

		Order entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Order with primary key" );
		msg.append( orderId );
		
		OrderFetchOneSummary fetchOneSummary = new OrderFetchOneSummary( orderId );

		try {
			entity = OrderService.getOrderInstance().getOrder( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Order " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Order.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Order." );

		StringBuilder msg = new StringBuilder( "Failed to update a Order : " );        
		Order entity = read();
		UpdateOrderCommand command = generateUpdateCommand();
		command.setOrderId(entity.getOrderId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Order." );

			// for use later on...
			orderId = entity.getOrderId();

			OrderService proxy = OrderService.getOrderInstance();  

			proxy.updateOrder( command ).get();

			LOGGER.info( "-- Successfully saved Order - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + orderId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Order.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Order." );

		Order entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Order with id " + orderId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Order with id " + orderId );

			throw e;
		}

		try{
			OrderService.getOrderInstance().delete( new DeleteOrderCommand( entity.getOrderId() ) ).get();
			LOGGER.info( "-- Successfully deleted Order with id " + orderId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Order with id " + orderId );

			throw e;
		}
	}

	/**
	 * get all Orders.
	 */
	protected List<Order> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Orders:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Order : " );        
		List<Order> collection  = new ArrayList<>();

		try {
			// call the static get method on the OrderService
			collection = OrderService.getOrderInstance().getAllOrder();
			assertNotNull( collection, "An Empty collection of Order was incorrectly returned.");
			
			// Now print out the values
			Order entity = null;            
			Iterator<Order> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getOrderId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

